using System;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Text;using System.Xml;using System.Windows.Forms;using System.Drawing;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 DataGridView cutFill,footings,earthBalanceGrid;readonly List<CutFillInterval> cutIntervals=new List<CutFillInterval>();readonly List<EarthworkMaterial> earthSources=new List<EarthworkMaterial>();readonly List<FootingTakeoff> footingResults=new List<FootingTakeoff>();List<double> footingStock=new List<double>(CommercialBars.Lengths);List<StockAllocation> footingPlan=new List<StockAllocation>();NumericUpDown borrowSwell,borrowShrink,gravelAllowance;Label earthStatus;EarthworkBalance earthBalance;
 void AddEarthworkFootings(){
  cutFill=Grid(new[]{"Alignment / zone ID","Description","Start station","End station","Cut area start m2","Cut area end m2","Fill area start m2","Fill area end m2","Suitable soil %","Swell %","Bank shrink %","Distance m","Cut bank m3","Fill compacted m3","Status"},11);
  AddGrid("Cut & Fill",cutFill,"Average end area: volume = (start area + end area)/2 x station distance. Areas are m2, NOT depths or volumes. Station: metres or 0+020. Same alignment intervals must not overlap. Insert zero/change-point sections. Exclude beam/footing trenches already counted separately.");
  SetDefaults(cutFill,new Dictionary<int,string>{{8,"100"},{9,"20"},{10,"10"}});cutFill.Columns[8].ToolTipText="Percentage of cut material suitable for reuse; 0 means all unsuitable. Subject to material approval.";
  var labels=new List<string>{"Footing ID","Description","L m (X)","B m (Y)","T m","Qty","Exc depth m (blank=T+0.10)","Cover mm"};foreach(string mat in new[]{"Bottom X","Bottom Y","Top X","Top Y"})labels.AddRange(new[]{mat+" dia mm",mat+" spacing mm",mat+" pcs/footing"});labels.AddRange(new[]{"Extra ends m/bar (both ends)","Side forms","Suitable soil %","Swell %","Bank shrink %","Concrete MPa","Grade <=12mm","Grade >=16mm","Concrete m3","Forms m2","Rebar BUY kg","Excavation bank m3","Status"});footings=Grid(labels.ToArray(),28);AddCombo(footings,21,"Side forms",new[]{"Formed sides","Earth cast"});AddCombo(footings,25,"Concrete MPa",new[]{"21","28","35"});AddCombo(footings,26,"Grade <=12mm",new[]{"40","60"});AddCombo(footings,27,"Grade >=16mm",new[]{"40","60"});
  SetDefaults(footings,new Dictionary<int,string>{{2,"2"},{3,"2"},{4,"0.40"},{5,"1"},{7,"75"},{8,"16"},{9,"150"},{11,"16"},{12,"150"},{20,"0"},{21,"Formed sides"},{22,"100"},{23,"20"},{24,"10"},{25,"21"},{26,"40"},{27,"60"}});
  AddGrid("Footing Estimate",footings,"Rectangular flat footings; dimensions in m, cover in mm. X bars run along L; Y bars run along B. For EACH bar group enter spacing OR pieces; blank diameter = unused group. Cut = run - 2 cover + specified total end allowance. Top mat optional. Excavation allowance 0.30m each side, gravel 0.10m under footprint. Count shared pits only once.");
  footings.Columns[20].ToolTipText="Total extra length at BOTH ends of each bar, from approved hook/development detail. 0 = straight cut. Not a structural anchorage check. Commercial splices use saved material configuration.";
  var footPage=tabs.TabPages.Cast<TabPage>().First(p=>p.Text=="Footing Estimate");var footTools=footPage.Controls.OfType<FlowLayoutPanel>().First();Button(footTools,"New footing",()=>EditFooting(true));Button(footTools,"Edit footing",()=>EditFooting(false));Button(footTools,"Settings",ShowWorksSettings);Button(footTools,"Commercial lengths",()=>{var chosen=StockLengthPicker.Choose(this,footingStock);if(chosen!=null){footingStock=chosen;Recalculate();}});
  foreach(string output in new[]{"Rebar net kg","Backfill compacted m3","Gravel installed m3"}){int c=footings.Columns.Add(output,output);footings.Columns[c].ReadOnly=true;footings.Columns[c].Width=155;}
  for(int c=6;c<28;c++)footings.Columns[c].Visible=false;var advanced=new CheckBox{Text="Show reinforcement inputs",AutoSize=true,Padding=new Padding(8,6,0,0)};advanced.CheckedChanged+=(s,e)=>{for(int c=6;c<25;c++)footings.Columns[c].Visible=advanced.Checked;};footTools.Controls.Add(advanced);
  var balancePage=new TabPage("Overall Earthwork & Gravel Summary");earthBalanceGrid=Grid(new[]{"Material / quantity","Quantity","Unit"},0);earthBalanceGrid.AllowUserToAddRows=false;earthBalanceGrid.Columns[0].Width=540;earthBalanceGrid.Columns[1].Width=160;earthBalanceGrid.Columns[2].Width=130;var controls=new FlowLayoutPanel{Dock=DockStyle.Top,Height=70,Padding=new Padding(8)};controls.Controls.Add(new Label{Text="Common borrow soil: swell %",AutoSize=true,Padding=new Padding(0,8,0,0)});borrowSwell=new NumericUpDown{Minimum=0,Maximum=200,DecimalPlaces=2,Value=20,Width=90};controls.Controls.Add(borrowSwell);controls.Controls.Add(new Label{Text="Bank shrink %",AutoSize=true,Padding=new Padding(0,8,0,0)});borrowShrink=new NumericUpDown{Minimum=0,Maximum=99,DecimalPlaces=2,Value=10,Width=90};controls.Controls.Add(borrowShrink);controls.Controls.Add(new Label{Text="Gravel purchase allowance %",AutoSize=true,Padding=new Padding(0,8,0,0)});gravelAllowance=new NumericUpDown{Minimum=0,Maximum=100,DecimalPlaces=2,Value=5,Width=80};controls.Controls.Add(gravelAllowance);gravelAllowance.ValueChanged+=(s,e)=>{if(!filling)Recalculate();};
  borrowSwell.ValueChanged+=(s,e)=>{if(!filling)Recalculate();};borrowShrink.ValueChanged+=(s,e)=>{if(!filling)Recalculate();};earthStatus=new Label{Dock=DockStyle.Top,Height=80,Padding=new Padding(8),Text="Overall material balance: suitable excavation from cut/fill, beams and footings is shared before common borrow. Final embankment quantities are LOOSE m3. Exclude overlapping excavation/fill from inputs; no automatic geometric overlap deduction."};var soilHelp=new ToolTip{ShowAlways=true};soilHelp.SetToolTip(borrowSwell,"Borrow bank-to-loose expansion; default 20% is an estimating assumption, not a universal soil standard.");soilHelp.SetToolTip(borrowShrink,"Borrow bank-to-compacted volume reduction; default 10% is an assumption, NOT a Proctor density target. Loose required = compacted gap / (1-shrink%) x (1+swell%).");soilHelp.SetToolTip(gravelAllowance,"Separate purchase ADDITION: default 5% means installed gravel x 1.05. Example basis: NTC CAR RFQ 036 (2020), G1 gravel bedding. Change to project specification. No soil swell/shrink added to gravel again.");FormClosed+=(sender,e)=>soilHelp.Dispose();balancePage.Controls.Add(earthBalanceGrid);balancePage.Controls.Add(earthStatus);balancePage.Controls.Add(controls);tabs.TabPages.Add(balancePage);
 }
 void SetDefaults(DataGridView grid,Dictionary<int,string> values){Action<DataGridViewRow> apply=row=>{foreach(var item in values)if(row.Cells[item.Key].Value==null)row.Cells[item.Key].Value=item.Value;};grid.DefaultValuesNeeded+=(s,e)=>apply(e.Row);grid.RowsAdded+=(s,e)=>{if(!filling)for(int n=e.RowIndex;n<e.RowIndex+e.RowCount;n++)if(!grid.Rows[n].IsNewRow)apply(grid.Rows[n]);};}
 static double OptionalNumber(DataGridViewRow r,int col,double value=0){return Cell(r,col)==""?value:Number(r,col);}
 void RecalculateEarthworks(){if(cutFill==null||footings==null||earthStatus==null||borrowSwell==null||borrowShrink==null||gravelAllowance==null)return;cutIntervals.Clear();earthSources.Clear();footingResults.Clear();earthBalance=null;
  foreach(DataGridViewRow r in cutFill.Rows){if(r.IsNewRow||Empty(r))continue;r.Tag=null;for(int c=11;c<15;c++)r.Cells[c].Value="";try{var q=new CutFillInterval{Alignment=Cell(r,0),Start=QuantityMath.Station(Cell(r,2)),End=QuantityMath.Station(Cell(r,3)),CutStart=OptionalNumber(r,4),CutEnd=OptionalNumber(r,5),FillStart=OptionalNumber(r,6),FillEnd=OptionalNumber(r,7)};q.Validate();var soil=new EarthworkMaterial{Id=Cell(r,0)+" "+Cell(r,2)+"-"+Cell(r,3),Source="Cut & fill",Bank=q.Cut,Fill=q.Fill,Reusable=OptionalNumber(r,8,100),Swell=OptionalNumber(r,9,20),Shrink=OptionalNumber(r,10,10)};soil.Validate();cutIntervals.Add(q);earthSources.Add(soil);r.Tag=q;r.Cells[11].Value=(q.End-q.Start).ToString("0.00");r.Cells[12].Value=q.Cut.ToString("0.00");r.Cells[13].Value=q.Fill.ToString("0.00");r.Cells[14].Value="Estimated";}catch(Exception x){errors.Add("Cut/fill "+Cell(r,0)+": "+x.Message);r.Cells[14].Value=x.Message;}}
  try{CutFillInterval.CheckOverlap(cutIntervals);}catch(Exception x){errors.Add(x.Message);}
  var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  foreach(DataGridViewRow r in footings.Rows){if(r.IsNewRow||Empty(r))continue;r.Tag=null;for(int c=28;c<36;c++)r.Cells[c].Value="";try{if(!ids.Add(Cell(r,0)))throw new Exception("Duplicate footing ID");double fc=OptionalNumber(r,25,21);int small=(int)OptionalNumber(r,26,40),large=(int)OptionalNumber(r,27,60);if(!new[]{21.0,28,35}.Contains(fc)||!new[]{40,60}.Contains(small)||!new[]{40,60}.Contains(large))throw new Exception("Choose concrete 21/28/35 and steel Grade 40/60.");var cfg=CalculationStore.Resolve(fc,small,small==40?275:420,large,large==40?275:420);var bars=new FootingBarSpec[4];for(int n=0;n<4;n++){int c=8+3*n;double dia=OptionalNumber(r,c),count=OptionalNumber(r,c+2);if(dia!=Math.Truncate(dia)||count!=Math.Truncate(count))throw new Exception("Bar diameter/count must be whole numbers.");bars[n]=new FootingBarSpec{Diameter=(int)dia,Spacing=OptionalNumber(r,c+1),Count=(int)count};}double thickness=Number(r,4);var q=FootingTakeoff.Calculate(Cell(r,0),Cell(r,1),Number(r,2),Number(r,3),thickness,Count(r,5),OptionalNumber(r,6,thickness+.1),OptionalNumber(r,7,75),Cell(r,21)!="Earth cast",bars,OptionalNumber(r,20),cfg,OptionalNumber(r,23,20),OptionalNumber(r,24,10),OptionalNumber(r,22,100));footingResults.Add(q);earthSources.Add(q.Soil);r.Tag=q;r.Cells[28].Value=q.Concrete.ToString("0.00");r.Cells[29].Value=q.Forms.ToString("0.00");r.Cells[31].Value=q.Excavation.ToString("0.00");r.Cells[32].Value="Estimated";r.Cells[33].Value=q.Steel.Result.Total.ToString("0.00");r.Cells[34].Value=q.Backfill.ToString("0.00");r.Cells[35].Value=q.Gravel.ToString("0.00");}catch(Exception x){errors.Add("Footing "+Cell(r,0)+": "+x.Message);r.Cells[32].Value=x.Message;}}
  // Each material configuration carries its own lap length; never substitute another grade/strength profile.
  footingPlan=new List<StockAllocation>();var materialGroups=footings.Rows.Cast<DataGridViewRow>().Where(row=>row.Tag is FootingTakeoff).GroupBy(row=>OptionalNumber(row,25,21).ToString(CultureInfo.InvariantCulture)+"|"+OptionalNumber(row,26,40)+"|"+OptionalNumber(row,27,60));foreach(var group in materialGroups){var sample=group.First();int gs=(int)OptionalNumber(sample,26,40),gl=(int)OptionalNumber(sample,27,60);var cfg=CalculationStore.Resolve(OptionalNumber(sample,25,21),gs,gs==40?275:420,gl,gl==40?275:420);footingPlan.AddRange(CommercialBars.Allocate(group.Select(row=>((FootingTakeoff)row.Tag).Steel),cfg,footingStock));}foreach(DataGridViewRow row in footings.Rows){var q=row.Tag as FootingTakeoff;if(q==null)continue;var plan=footingPlan.Where(x=>x.Entry==q.Steel).ToList();if(plan.Any(x=>x.Choice==null)){errors.Add("Footing "+q.Id+": unresolved commercial bar cut");row.Cells[32].Value="Unresolved stock cut";}row.Cells[30].Value=plan.Sum(x=>x.Purchase).ToString("0.00");}
  try{earthSources.AddRange(beam.WorksEarthworkMaterials());earthBalance=EarthworkBalance.Calculate(earthSources,(double)borrowSwell.Value,(double)borrowShrink.Value);}catch(Exception x){errors.Add("Overall earthworks: "+x.Message);}
  earthBalanceGrid.Rows.Clear();if(earthBalance!=null)foreach(var row in EarthSummaryRows())earthBalanceGrid.Rows.Add(row);earthStatus.Text=(errors.Count>0?"REVIEW / PARTIAL INPUTS: fix errors before export.\n":"")+"Shared suitable soil from cut/fill, beam trenches and footing pits. Final embankment quantities are LOOSE material before compaction. Sources used in entry order (cut/fill, footings, beams); no haul-distance optimization. Exclude overlapping trenches/fill from inputs.";
 }
 List<object[]> EarthSummaryRows(){var e=earthBalance;return new List<object[]>{new object[]{"Excavation (in-place / bank)",e.Excavation,"m3"},new object[]{"Required space after compaction (reference)",e.Fill,"m3"},new object[]{"Embankment FROM EXCAVATION - loose material",e.LooseFromExcavation,"m3"},new object[]{"Embankment FROM COMMON BORROW - loose material to buy",e.LooseCommonBorrow,"m3"},new object[]{"Suitable surplus for disposal / stockpile - loose",e.LooseSurplus,"m3"},new object[]{"Unsuitable material for disposal - loose",e.UnsuitableLoose,"m3"},new object[]{"Beam gravel installed volume",beam.WorksGravel(),"m3"},new object[]{"Footing gravel installed volume",footingResults.Sum(x=>x.Gravel),"m3"},new object[]{"TOTAL gravel installed volume",beam.WorksGravel()+footingResults.Sum(x=>x.Gravel),"m3"},new object[]{"TOTAL GRAVEL TO BUY - loose material",(beam.WorksGravel()+footingResults.Sum(x=>x.Gravel))*(1+(double)gravelAllowance.Value/100),"m3"}};}
 void WriteEarthSettings(XmlElement root){WriteMaterialDefaults(root);root.SetAttribute("accessoryLapMm",accessoryLap.Value.ToString(CultureInfo.InvariantCulture));root.SetAttribute("gravelAllowance",gravelAllowance.Value.ToString(CultureInfo.InvariantCulture));root.SetAttribute("footingStock",CommercialBars.FormatLengths(footingStock));root.SetAttribute("borrowSwell",borrowSwell.Value.ToString(CultureInfo.InvariantCulture));root.SetAttribute("borrowShrink",borrowShrink.Value.ToString(CultureInfo.InvariantCulture));}
 void ReadEarthSettings(XmlElement root){ReadMaterialDefaults(root);accessoryLap.Value=root.HasAttribute("accessoryLapMm")?decimal.Parse(root.GetAttribute("accessoryLapMm"),CultureInfo.InvariantCulture):150;gravelAllowance.Value=root.HasAttribute("gravelAllowance")?decimal.Parse(root.GetAttribute("gravelAllowance"),CultureInfo.InvariantCulture):5;footingStock=CommercialBars.ParseLengths(root.GetAttribute("footingStock"));borrowSwell.Value=root.HasAttribute("borrowSwell")?decimal.Parse(root.GetAttribute("borrowSwell"),CultureInfo.InvariantCulture):20;borrowShrink.Value=root.HasAttribute("borrowShrink")?decimal.Parse(root.GetAttribute("borrowShrink"),CultureInfo.InvariantCulture):10;}
 void AppendEarthworkReport(StringBuilder b,bool detailed){if(earthBalance==null)throw new Exception("Resolve earthwork inputs first.");b.AppendLine();b.AppendLine("OVERALL EARTHWORK MATERIAL BALANCE | FINAL QUANTITIES");foreach(var row in EarthSummaryRows())b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-63}{1,13:0.00} {2}",row[0],row[1],row[2]));b.AppendLine("Only the two EMBANKMENT quantities are material requirements before compaction. No additional allowance.");b.AppendLine("Shared soil balance supersedes individual beam/footing borrow estimates. Do not add both.");b.AppendLine("Gravel BUY = installed gravel x (1 + "+gravelAllowance.Value.ToString("0.00")+"% purchase allowance). Separate from soil swell/shrink; do not apply twice.");if(!detailed)return;b.AppendLine("CUT & FILL | average end areas x station distance");foreach(var q in cutIntervals)b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0} | {1:0.00}-{2:0.00}m: cut ({3:0.00}+{4:0.00})/2 x {5:0.00} = {6:0.00}m3; fill {7:0.00}m3",q.Alignment,q.Start,q.End,q.CutStart,q.CutEnd,q.End-q.Start,q.Cut,q.Fill));b.AppendLine("SOURCE CHECK | bank excavation / compacted space / suitable % / swell % / bank shrink %");foreach(var s in earthSources)b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0} {1}: {2:0.00} / {3:0.00} / {4:0.00} / {5:0.00} / {6:0.00}",s.Source,s.Id,s.Bank,s.Fill,s.Reusable,s.Swell,s.Shrink));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Common borrow loose = unfilled compacted space / {0:0.00} x {1:0.00}",1-earthBalance.BorrowShrink/100,1+earthBalance.BorrowSwell/100));b.AppendLine("No geometric overlap deductions, slopes, haul-distance optimization or material compatibility checks. Suitable-soil % requires project approval.");}
 List<StockAllocation> projectRebarPlan=new List<StockAllocation>();
 void RefreshProjectRebarPlan(){if(footings==null||beam==null||slab==null)return;projectRebarPlan=beam.WorksPlan().Concat(slab.WorksPlan()).Concat(footingPlan).ToList();RebarOffcuts.Allocate(projectRebarPlan);foreach(DataGridViewRow row in footings.Rows){var footing=row.Tag as FootingTakeoff;if(footing!=null)row.Cells[30].Value=footingPlan.Where(a=>a.Entry==footing.Steel).Sum(a=>a.Purchase).ToString("0.00");}}
 void AppendFootingReport(StringBuilder b,bool detailed){b.AppendLine();b.AppendLine("FOOTING WORKS | QUANTITIES TO BUY");b.AppendLine("Selected commercial lengths: "+CommercialBars.FormatLengths(footingStock)+" m");b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Concrete {0:0.00} m3 | Side forms {1:0.00} m2 | Rebar BUY {2:0.00} kg",footingResults.Sum(x=>x.Concrete),footingResults.Sum(x=>x.Forms),footingPlan.Sum(x=>x.Purchase)));PurchaseReports.Summary(b,footingPlan,false);foreach(var f in footingResults){b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0} | {1} | {2:0.00} x {3:0.00} x {4:0.00}m x {5} pcs",f.Id,f.Description,f.Length,f.Width,f.Thickness,f.Quantity));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Concrete {0:0.00} m3 | Forms {1:0.00} m2 | Exc {2:0.00} bank m3",f.Concrete,f.Forms,f.Excavation));if(detailed){b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Pit ({0:0.00}+0.60) x ({1:0.00}+0.60) x {2:0.00} x {3}; gravel {4:0.00}m3; backfill space {5:0.00}m3",f.Length,f.Width,f.Depth,f.Quantity,f.Gravel,f.Backfill));PurchaseReports.Entry(b,footingPlan.Where(a=>a.Entry==f.Steel).ToList(),f.Quantity,reportDetail.SelectedIndex==2);}}b.AppendLine("Cuts use entered cover/end allowance. Splices use saved material profile. No pedestal, slope, dowel or anchorage design inferred. Earthwork material requirements: use OVERALL balance.");}
 void EarthworksExcel(List<WorksExcelTable> tables){if(earthBalance==null)throw new Exception("Earthwork balance is unavailable.");tables.Add(new WorksExcelTable("POW Overall Earthworks",new[]{"Item (permanent rows)","Quantity","Unit"},EarthSummaryRows()));var rows=new List<object[]>();foreach(var s in earthSources)rows.Add(new object[]{s.Source,s.Id,s.Bank,s.Fill,s.Reusable,s.Swell,s.Shrink,s.LooseAvailable,s.CompactedAvailable});tables.Add(new WorksExcelTable("POW Earthwork Sources",new[]{"Source","ID","Excavation bank m3","Compacted space m3","Suitable %","Swell %","Bank shrink %","Suitable loose m3","Suitable compacted yield m3"},rows));rows=new List<object[]>();foreach(var q in cutIntervals)rows.Add(new object[]{q.Alignment,q.Start,q.End,q.End-q.Start,q.CutStart,q.CutEnd,q.FillStart,q.FillEnd,q.Cut,q.Fill});tables.Add(new WorksExcelTable("POW Cut Fill",new[]{"Alignment","Start m","End m","Distance m","Cut start m2","Cut end m2","Fill start m2","Fill end m2","Cut bank m3","Fill compacted m3"},rows));rows=new List<object[]>();foreach(var f in footingResults)rows.Add(new object[]{f.Id,f.Description,f.Length,f.Width,f.Thickness,f.Quantity,f.Concrete,f.Forms,footingPlan.Where(x=>x.Entry==f.Steel).Sum(x=>x.Purchase),f.Excavation,f.Gravel,f.Backfill});tables.Add(new WorksExcelTable("POW Footings",new[]{"ID","Description","L m","B m","T m","Qty","Concrete m3","Forms m2","Rebar BUY kg","Excavation bank m3","Gravel m3","Compacted space m3"},rows));}
}
